#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Edge { int to; ll w; };

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int n; int k;
	if (!(cin >> n >> k)) return 0;
	vector<vector<Edge>> g(n + 1);
	for (int i = 0; i < n - 1; ++i) {
		int u, v; ll w;
		cin >> u >> v >> w;
		g[u].push_back({v, w});
		g[v].push_back({u, w});
	}

	// 计算加权直径作为二分上界
	auto farthest = [&](int start) {
		vector<ll> dist(n + 1, -1);
		vector<int> st;
		st.reserve(n);
		st.push_back(start);
		dist[start] = 0;
		vector<int> parent(n + 1, -1);
		while (!st.empty()) {
			int u = st.back(); st.pop_back();
			for (auto &e : g[u]) {
				int v = e.to;
				if (v == parent[u]) continue;
				parent[v] = u;
				dist[v] = dist[u] + e.w;
				st.push_back(v);
			}
		}
		int idx = 1;
		for (int i = 1; i <= n; ++i) if (dist[i] > dist[idx]) idx = i;
		return pair<int,ll>(idx, dist[idx]);
	};
	int a = farthest(1).first;
	auto [b, dia] = farthest(a);

	// 预处理：固定根1，建立父子关系、parent边权、后序序列
	vector<int> parent(n + 1, 0);
	vector<ll> pw(n + 1, 0);           // 与父亲相连的边权
	vector<vector<int>> children(n + 1);
	vector<int> post; post.reserve(n);

	{
		// 迭代式DFS生成后序
		vector<pair<int,int>> st;
		st.reserve(2*n);
		parent[1] = 0; pw[1] = 0;
		st.push_back({1, 0}); // 0: 进入, 1: 退出
		while (!st.empty()) {
			auto [u, t] = st.back(); st.pop_back();
			if (t == 0) {
				st.push_back({u, 1});
				for (auto &e : g[u]) {
					int v = e.to;
					if (v == parent[u]) continue;
					parent[v] = u;
					pw[v] = e.w;
					children[u].push_back(v);
					st.push_back({v, 0});
				}
			} else {
				post.push_back(u);
			}
		}
	}

	vector<ll> up(n + 1, 0);

	auto feasible = [&](ll D) -> bool {
		long long cuts = 0;
		for (int idx = (int)post.size() - 1; idx >= 0; --idx) {
			int u = post[idx];
			vector<ll> A;
			A.reserve(children[u].size());
			for (int v : children[u]) {
				ll t = up[v] + pw[v];
				if (t > D) {
					// 必须切断这条边
					++cuts;
				} else {
					A.push_back(t);
				}
			}
			sort(A.begin(), A.end());
			while ((int)A.size() >= 2 && A.back() + A[(int)A.size() - 2] > D) {
				A.pop_back();
				++cuts;
			}
			up[u] = A.empty() ? 0LL : A.back();
			if (cuts > k) return false; // 剪枝
		}
		return cuts <= k;
	};

	ll lo = 0, hi = dia;
	while (lo < hi) {
		ll mid = (lo + hi) >> 1;
		if (feasible(mid)) hi = mid;
		else lo = mid + 1;
	}
	cout << lo << "\n";
	return 0;
}
