import java.io.*;
import java.util.*;

/**
 * 二分 + 树形DP可行性检查（自底向上，贪心删除最大的分支直到最大两条之和 <= D）
 */
public class Main {
	static class FastScanner {
		BufferedInputStream in;
		byte[] buffer = new byte[1 << 16];
		int ptr = 0, len = 0;
		FastScanner(InputStream is) { in = new BufferedInputStream(is); }
		int read() throws IOException {
			if (ptr >= len) {
				len = in.read(buffer); ptr = 0;
				if (len <= 0) return -1;
			}
			return buffer[ptr++];
		}
		int nextInt() throws IOException {
			int c, s = 1, x = 0;
			do { c = read(); } while (c <= ' ');
			if (c == '-') { s = -1; c = read(); }
			while (c > ' ') { x = x * 10 + (c - '0'); c = read(); }
			return x * s;
		}
	}
	static int n, k, m, idx;
	static int[] head, to, next, parent;
	static long[] w, pw, up;
	static ArrayList<Integer>[] children;
	static int[] post; // 后序
	static int postPtr;

	static void addEdge(int u, int v, int ww) {
		to[idx] = v; w[idx] = ww; next[idx] = head[u]; head[u] = idx++;
	}

	static int farthestNode(int start) {
		long[] dist = new long[n + 1];
		Arrays.fill(dist, -1);
		int[] par = new int[n + 1];
		Arrays.fill(par, -1);
		int[] st = new int[n];
		int top = 0;
		st[top++] = start;
		dist[start] = 0;
		while (top > 0) {
			int u = st[--top];
			for (int e = head[u]; e != -1; e = next[e]) {
				int v = to[e];
				if (v == par[u]) continue;
				par[v] = u;
				dist[v] = dist[u] + w[e];
				st[top++] = v;
			}
		}
		int idxNode = 1;
		for (int i = 1; i <= n; ++i) {
			if (dist[i] > dist[idxNode]) idxNode = i;
		}
		return idxNode;
	}

	static long farthestDist(int start) {
		long[] dist = new long[n + 1];
		Arrays.fill(dist, -1);
		int[] par = new int[n + 1];
		Arrays.fill(par, -1);
		int[] st = new int[n];
		int top = 0;
		st[top++] = start;
		dist[start] = 0;
		while (top > 0) {
			int u = st[--top];
			for (int e = head[u]; e != -1; e = next[e]) {
				int v = to[e];
				if (v == par[u]) continue;
				par[v] = u;
				dist[v] = dist[u] + w[e];
				st[top++] = v;
			}
		}
		long best = 0;
		for (int i = 1; i <= n; ++i) best = Math.max(best, dist[i]);
		return best;
	}

	static boolean feasible(long D) {
		long cuts = 0;
		// 自底向上处理
		for (int p = postPtr - 1; p >= 0; --p) {
			int u = post[p];
			int sz = children[u].size();
			long[] arr = new long[sz];
			int tsz = 0;
			for (int i = 0; i < sz; ++i) {
				int v = children[u].get(i);
				long t = up[v] + pw[v];
				if (t > D) {
					cuts++;
				} else {
					arr[tsz++] = t;
				}
			}
			if (tsz > 1) {
				Arrays.sort(arr, 0, tsz);
				while (tsz >= 2 && arr[tsz - 1] + arr[tsz - 2] > D) {
					tsz--; // 删除最大的
					cuts++;
				}
			}
			up[u] = (tsz > 0 ? arr[tsz - 1] : 0L);
			if (cuts > k) return false;
		}
		return cuts <= k;
	}

	public static void main(String[] args) throws Exception {
		FastScanner fs = new FastScanner(System.in);
		n = fs.nextInt(); k = fs.nextInt();
		m = 2 * (n - 1);
		head = new int[n + 1];
		to = new int[m];
		next = new int[m];
		w = new long[m];
		Arrays.fill(head, -1); idx = 0;
		for (int i = 0; i < n - 1; ++i) {
			int u = fs.nextInt(), v = fs.nextInt(), ww = fs.nextInt();
			addEdge(u, v, ww);
			addEdge(v, u, ww);
		}

		// 直径
		int a = farthestNode(1);
		long dia = farthestDist(a);

		// 固定根1，构建父子与后序
		parent = new int[n + 1];
		pw = new long[n + 1];
		children = new ArrayList[n + 1];
		for (int i = 1; i <= n; ++i) children[i] = new ArrayList<>();
		post = new int[n]; postPtr = 0;
		// 迭代DFS生成后序
		int[][] st = new int[2 * n][2]; // (u, state)
		int top = 0;
		st[top][0] = 1; st[top][1] = 0; top++;
		parent[1] = 0; pw[1] = 0;
		while (top > 0) {
			int u = st[--top][0];
			int state = st[top][1]; // 读取刚弹出的state
			if (state == 0) {
				// 重新压回退出态
				st[top][0] = u; st[top][1] = 1; top++;
				for (int e = head[u]; e != -1; e = next[e]) {
					int v = to[e];
					if (v == parent[u]) continue;
					parent[v] = u;
					pw[v] = w[e];
					children[u].add(v);
					st[top][0] = v; st[top][1] = 0; top++;
				}
			} else {
				post[postPtr++] = u;
			}
		}

		up = new long[n + 1];

		long lo = 0, hi = dia;
		while (lo < hi) {
			long mid = (lo + hi) >>> 1;
			if (feasible(mid)) hi = mid;
			else lo = mid + 1;
		}
		System.out.println(lo);
	}
}
